    code: "// Approach: Shift a one to zero-based position i and AND it with the number. Use an unsigned type to\n//   avoid signed-shift pitfalls. The task gives a valid bit index (0 to 31).\n#include <cstdint>\nusing namespace std;\nbool isBitSet(uint32_t value, int i) {\n    return (value & (uint32_t(1) << i)) != 0;\n}",
